     def ser_model(self) -> str:
         return f"fixed[{self.root}]"

     def __len__(self) -> int:
         """Return the length of an instance of the FixedType class."""
         return self.root

     def __str__(self) -> str:
         """Return the string representation."""
         return f"fixed[{self.root}]"

